        'Rajasthan': ['Ajmer', 'Alwar', 'Banswara', 'Barmer', 'Bharatpur', 'Bhilwara', 'Bikaner', 'Bundi', 'Chittorgarh', 'Churu', 'Dausa', 'Dholpur', 'Hanumangarh', 'Jaipur', 'Jaisalmer', 'Jalore', 'Jhunjhunu', 'Jodhpur', 'Kota', 'Nagaur', 'Pali', 'Sawai Madhopur', 'Sikar', 'Sriganganagar', 'Tonk', 'Udaipur'],
